"""Own bounded Biology14 author inputs and raster role prompts, no approvals."""
import hashlib,json
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path.cwd();OWN=Path(__file__).resolve().parent;REL=OWN.relative_to(ROOT).as_posix()
CANON='curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_BIOLOGIE.de.json'
KINDS='curricula/DE/Gymnasium/quality/goal-book-publication/biologie.semantic-kinds.json'
REG='curricula/DE/Gymnasium/quality/deep-understanding-rollout/de-gymnasium-math-physics.config.json'
SOURCE='curricula/DE/Gymnasium/input/BY/gymnasium/source-extraction/DE_BY_BIOLOGIE_GYMNASIUM_LEHRPLANPLUS.source-extraction.json'
OLD='curricula/DE/Gymnasium/quality/goal-evidence/2026-10-08/biologie-upper-communication-evaluation-whole-author-resumed-v1'
IDS=['19fe5734-ea3e-5e3f-bd69-692955787168','0beb4ca2-2437-557a-9db2-ccda1cbcfa0a','fe8cb55a-00e9-5964-880a-2634125cfd41','4d1b2991-9279-591f-a0b1-0ff184ffd8e5','4edb6169-1202-5651-b23f-dcb6eddb58ba','d5548c48-7c0a-562e-b09b-b101c6ed732b','82acfbde-9ce8-5658-892e-4dcfb1c3a1f1','328fd9d3-d3c3-5731-a8da-a909143d3962','19bcea3a-af7a-5feb-b083-d11bd51303a0','b66372fc-f72d-5686-9570-1939ed3fbd2a','8375310d-1f7e-542d-9969-55ad4bd37f7c','4f741ece-e38e-5c6d-ae59-c0f017753177','788cda1f-8ca3-5241-8d73-50d9952e9da3','41c14647-9747-58d8-b97d-d1dce33e980e']
def write(name,data):
 p=OWN/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def bind(path):
 p=ROOT/path;b=p.read_bytes();return dict(path=path,sha256='sha256:'+hashlib.sha256(b).hexdigest(),bytes=len(b))
def snapshot(path,name):
 p=OWN/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes((ROOT/path).read_bytes());return {**bind(path),'snapshotPath':p.relative_to(ROOT).as_posix()}
canon=json.loads((ROOT/CANON).read_text());allgoals=canon['goals'];g={a['id']:a for a in allgoals};kinds=json.loads((ROOT/KINDS).read_text());reg=json.loads((ROOT/REG).read_text());bio=next(a for a in reg['subjects'] if a['subject']=='biologie')
source=json.loads((ROOT/SOURCE).read_text());sg={a['id']:a for a in source['sourceGoals']};passages={a.get('id',a.get('passageId')):a for a in source['passages']}
bindings=[snapshot(CANON,'input/current-canonical479.original.snapshot.json'),snapshot(KINDS,'input/current-kinds394.original.snapshot.json'),snapshot(REG,'input/current-central-registry.original.snapshot.json'),snapshot(SOURCE,'input/BY-biology-original.source-extraction.json')]
reuse={}
for key in ['semanticAtomicityConfigPath','memoryReviewConfigPath']:
 cfg=json.loads((ROOT/bio[key]).read_text());records=[json.loads(a) for a in (ROOT/cfg['reviewPath']).read_text().splitlines() if a.strip()];selected=[a for a in records if a.get('goalId') in IDS];assert len(selected)==14
 reuse[key]={'configBinding':bind(bio[key]),'reviewBinding':bind(cfg['reviewPath']),'unchangedSelectedRows':selected,'role':'existing current decisions reused, not new author reviews'}
 bindings.append(snapshot(cfg['reviewPath'],'input/'+('atomicity' if 'Atomicity' in key else 'memory')+'.current-full.original.jsonl'))
contexts=[]
for i in IDS:
 a=g[i];sid=a['extendedData']['provenance']['sourceGoalId'];assert sid in sg
 contexts.append(dict(goalId=i,wholeCurrentGoal=a,wholeParents=[p for p in allgoals if i in p.get('contains',[])],wholePrerequisites=[g[r] for r in a.get('requires',[])],wholeConsumers=[p for p in allgoals if i in p.get('requires',[])],wholeSourceGoal=sg[sid],wholeSourcePassage=passages.get(sg[sid]['passageId']),descriptionChanges=[],independentReviewStatus='pending'))
write('whole-fourteen-current-goals-source-and-context.input.snapshot.json',dict(schemaVersion=1,role='neutral whole author input',entries=contexts,scopeGoalIds=IDS,bindings=bindings,existingAtomicityMemoryReuse=reuse,currentCanonicalNodes=len(allgoals),currentCurricularAtoms=sum(a['semanticKind']=='curricularAtomic' for a in kinds['decisions']),activeWrites=[],humanApproval=False))
oldreceipt=json.loads((ROOT/OLD/'primary/official-source-retrieval.author.receipt.json').read_text());primary=[]
for a in oldreceipt['entries']:
 b=bind(a['originalPath']);assert b['sha256']==a['sha256'] and b['bytes']==a['bytes'];primary.append({**a,'actualCurrentOriginalBinding':b,'visibleBinding':bind(a['visibleExtractionPath']),'reuseStatus':'existing original whole primary bytes; new goal-specific interpretation pending'})
write('existing-four-whole-official-primary-bindings.author.json',dict(schemaVersion=1,entries=primary,retrievalReceiptBinding=bind(OLD+'/primary/official-source-retrieval.author.receipt.json'),newDownload=False,newIndependentApproval=False))
plans=[
('Zwei Teams prüfen eine Erklärung für Keimung','Zwei kleine Arbeitsgruppen betrachten dieselbe sichere Kressekeimung, links eine bloße Idee als Sprechblase, mittig ein großes einfaches Vergleichsgefäßpaar, rechts ein zweites Team mit erneutem Vergleich. Offene Pfeile verbinden Idee, Belege und Nachprüfen; keine Siegerkrone und kein endgültiges Wahrheitshäkchen.','"Idee", "Belege", "Nachprüfen"','Evidenz und theoriegeleitete Erklärung gehören zusammen; eine Replikation ist kein Beweis ewiger Gültigkeit.'),
('Biologische Basiskonzepte am Blatt','Ein großes Blatt mit gut erkennbaren Blattadern und einer schematischen Spaltöffnung. Sonnenlicht, Wasser und ein CO₂-Symbol beziehen sich auf das Blatt; daneben eine Lupe zur Struktur und ein offener Kreispfeil zum Austausch. Freundliche Szene mit wenigen großen Elementen.','"Struktur", "Austausch", "Energie"','Ein Blatt ist ein lebendes offenes System. Sonnenlicht ist Energie, Wasser und CO₂ sind Stoffe. Keine ATP- oder Molekülstrukturen erfinden.'),
('Eine aus Theorie abgeleitete Vorhersage','Eine Schülerin betrachtet zwei gleichartige, gleich große junge Pflanzen: ein Exemplar in einem hellen, eines in einem abgedunkelten Bereich. Ein großes Fragezeichen und eine eigene transparente Gedankenblase mit einer möglichen künftigen Pflanzenreaktion zeigen eine Vorhersage, kein bereits gemessenes Ergebnis.','"Hypothese", "Prüfen"','Beide Pflanzen sind gleiche Art; die abgebildete Veränderung ist klar als Vermutung erkennbar. Kein Lichtmangel als generell tödlich oder Keimung als generell lichtpflichtig darstellen.'),
('Lebende Systeme von klein bis groß','Vier große zusammenhängende Vergrößerungs-/Verkleinerungsfenster: abstrakter Pigmentknoten ohne chemische Struktur, Blattgewebe, Baumgruppe und Erde mit Vegetation. Eine verständliche Verbindung führt von der kleinen Ebene zu Ökosystem und Biosphäre. Die Erde ist eine Ebene des Systems, keine mathematische Hochrechnungsgarantie.','"Molekül", "Blatt", "Wald", "Biosphäre"','Pigment als abstrakten farbigen Stoffknoten zeigen, keine angebliche echte Molekülstruktur; keine falsche DNA oder zusätzliche mikroskopische Organe.'),
('Stoffe verbinden Organismen und Umwelt','Ein großer Baum gibt ein abgefallenes Blatt ab; ein Regenwurm und Pilz als Zersetzer stehen beim Laub, Wurzeln nehmen Wasser und Mineralstoffe aus dem Boden auf. Große klar gerichtete Pfeile illustrieren organischen Stofffluss und Rückführung von Mineralstoffen, Sonnenlicht kommt von oben als Energieinput.','"Stoffe", "Energie"','Wurzelaufnahme von Wasser/Mineralstoffen darstellen, nicht von ganzen Blättern; Energie nicht als vollständig geschlossenen Kreislauf zeigen.'),
('Von einer Beobachtung zu einer Frage','Eine Jugendliche betrachtet zwei Kressegefäße mit unterschiedlich feuchtem Substrat und verschiedener Keimung. Neben der Beobachtung steht eine große Frageblase; eine kleine transparente Gedankenblase zeigt eine mögliche Wasser-/Sauerstoff-Erklärung.','"Beobachtung", "Frage", "Hypothese"','Die Beobachtung legt einen überprüfbaren Zusammenhang nahe, beweist ihn nicht; kein allgemeiner Lichtbedarf aller Samen behauptet.'),
('Kontrollierter Vergleich und Protokoll','Zwei gleich große Pflanzengefäße gleicher Art unter gleichen Tageslichtbedingungen, ein Gefäß mäßig feucht und ein Gefäß trocken. Zwei gleiche große Thermometersymbole verweisen auf dieselbe Temperatur. Eine Lernende protokolliert mit zur eigenen Blickrichtung ausgerichtetem Heft; im Heft nur große schematische Zeichen, keine lesepflichtige Schrift.','"Vergleichen", "Protokoll"','Untersuchte Variable Wasser kenntlich machen; gleiche Art, Gefäß, Temperatur und Beleuchtung behalten. Keine gefährlichen Stoffe, kein Mundpipettieren.'),
('Messdaten sinnvoll digital erfassen','Ein Jugendlicher misst mit einem sicher befestigten Temperaturfühler neben einer Wasserpflanze; das Messkabel führt zu einem Tablet mit einem großen einfachen Punktdiagramm. Eine qualitative Blattbeobachtung steht daneben als großes Blattsymbol mit Lupe.','"Messen", "Auswerten"','Der Fühler berührt das Wasser und gehört zu Temperaturmessung, nicht Sauerstoffmessung. Kein fertiger exakter Temperaturwert, keine Kleinschrift oder erfundene Messsoftware.'),
('Sichere Techniken im Labor und draußen','Zwei große klar verbundene Szenen: links eine Lernende mit Schutzbrille am Schülermikroskop und fertigem Pflanzenpräparat auf rutschfester Fläche; rechts eine Lernende auf festem Uferweg, mit Stielkescher und Beobachtungsschale. Kein Betreten tiefer Gewässer.','"Sachgerecht", "Sicher"','Objektiv und Präparat richtig angeordnet, elektrische Geräte fern vom Wasser, keine Hand am offenen Netzanschluss. Tiere nur schonend kurz betrachten und ins Herkunftsgewässer zurücksetzen; keine Chemikalien oder unbekannten Kulturen.'),
('Datenmuster mit einer biologischen Theorie erklären','Ein großes gut lesbares schematisches Diagramm mit wenigen Punkten zeigt Sauerstoffproduktion einer Wasserpflanze: bei zunehmender Beleuchtung zunächst Anstieg, dann Plateau. Daneben die Pflanze und eine offene Frageblase zum limitierenden Faktor.','"Licht", "Sauerstoff", "Grenze"','Diagramm ist ausdrücklich schematisch, keine erfundenen genauen Messzahlen. Plateau bedeutet möglicher anderer limitierender Faktor; keine universelle unveränderte Naturkurve.'),
('Fehlerquellen und Modellgrenzen','Ein Blattmodell auf einer Tafel steht einer wirklichen Blattskizze gegenüber. Eine Lupe markiert eine ungleichmäßige Beleuchtung und ein leicht schief positioniertes Messgerät als mögliche Fehlerquelle, eine offene Grenze kennzeichnet das vereinfachte Modell.','"Daten", "Fehler", "Modell"','Keine automatische Verwerfung aller Daten darstellen, keine echte Messung als perfekt. Vereinfachung und Messfehler sind unterschiedliche Begriffe.'),
('Eine Hypothese am Gegenbefund prüfen','Zwei gleichartige Kressegefäße: eines unter Licht, eines eindeutig im Dunkeln; beide haben große sichtbar gekeimte Samen. Eine offene Gedankenkarte zur allgemeinen Lichtpflicht wird mit einer Lupe auf den Dunkelbefund bezogen.','"Hypothese", "Gegenbefund"','Nur das spezifische Modell einer nicht lichtpflichtigen Samenart darstellen. Keimung im Dunkeln ist ein Gegenbeispiel zur universellen Lichtpflicht, kein Beweis, dass kein Samen Licht benötigt.'),
('Biologischen Befund fachübergreifend erschließen','Ein großer Bach mit Fischen und einer Wasserprobe. Drei gut unterscheidbare Gedankenfenster verbinden Fischatmung als Biologie, gelösten Sauerstoff als Chemie und warmes/kaltes Wasser als Physik. Kein abgestorbener Fisch, keine Katastrophenwirkung.','"Biologie", "Chemie", "Physik"','Warmes Wasser kann weniger Sauerstoff lösen, aber Fischsterben nicht allein aus Temperatur ableiten. Offene Zusammenhänge, keine exakten Zahlen oder chemischen Kleinformeln.'),
('Prüfbare und vorläufige Erkenntnis','Zwei Teams beobachten in getrennten passenden Aufbauten dasselbe Blattphänomen; in der Mitte eine große offene Vergleichskarte mit zwei vereinbaren Ergebnissen und einer danebenliegenden neuen Frage. Ein Kreispfeil zeigt Wiederholung, die Frage bleibt offen.','"Wiederholen", "Vergleichen", "Weiterfragen"','Reproduzierbarkeit und intersubjektives Prüfen darstellen, keine Abstimmung über Wahrheit, kein endgültiges Freigabesiegel. Unabhängiges Wiederholen kann Bedingungen ändern und Erkenntnis präzisieren.')]
assert len(plans)==14
imageentries=[]
for ordinal,(i,(title,scene,labels,constraints)) in enumerate(zip(IDS,plans),1):
 prompt=f'''Use case: scientific-educational
Asset type: Lernzielbild für SkillPilot Biologie, notwendiger neuer PNG-Kandidat.
Aktuelles ganzes Ziel: {g[i]['title']}
Ganzes Lernziel: {g[i]['description']}
Primary request: {title}. {scene}
Style/medium: Freundliche, abstrakte, klare comicartige Rasterillustration, passend zur bestehenden SkillPilot-Bildlandschaft, helle ruhige Farben, dunkle deutliche Umrisse, kein Fotorealismus und keine steril-technische Neugestaltung.
Composition/framing: Ein PNG quer nahe16:9, etwa1600×900 Pixel oder nahe native Generatorgröße. Wenige große Motive mit viel freiem Raum. Hauptmotiv und fachlich entscheidende Details müssen bei360px Bildbreite und680px Bildbreite erkennbar bleiben.
Text (verbatim): Nur die großen gezielten deutschen Beschriftungen {labels}. Keine weitere Schrift, keine kleinteiligen Tabellen, keine kleingedruckten Achsenwerte.
Fachliche constraints: {constraints} Beispiele und Kurven sind schematische Modelle, keine behaupteten empirischen Versuchsergebnisse. Keine neue Kompetenz, kein Freigabe-/Mastery-/QA-Siegel im Bild.
Actor perspective: Heft-, Tafel-, Mess- und Tablet-Darstellungen sind für die handelnde Person richtig herum angeordnet; Papier darf nicht nur zum externen Betrachter gedreht sein. Falls Schrift in einem Heft bei dieser Perspektive nicht lesbar wäre, nur schematische Zeichen statt lesepflichtiger Schrift.
Avoid: Überfüllte Bildpanels, Kleinschrift, realistische Gesichter, technische CAD-Ästhetik, SVG-Ersatzzeichnung, Logos, Wasserzeichen, falsche Molekülstrukturen und dekorative fachlich bedeutungslose Pfeile.
'''
 path=OWN/'image-prompts'/f'{ordinal:02d}-{i}.prompt.de.md';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(prompt)
 imageentries.append(dict(ordinal=ordinal,goalId=i,wholeGoalDescriptionDe=g[i]['description'],promptPath=path.relative_to(ROOT).as_posix(),promptSha256='sha256:'+hashlib.sha256(path.read_bytes()).hexdigest(),imageRole=title,scientificConstraints=constraints,actualImagePresent=False,provider=None,independentApproval=False))
write('neutral-fourteen-image-prompts.author.entry.json',dict(schemaVersion=1,role='neutral goal-derived raster prompt handoff; no generated images or approvals',entries=imageentries,scopeGoalIds=IDS,inputWholeGoalBinding=bind(REL+'/whole-fourteen-current-goals-source-and-context.input.snapshot.json'),humanApproval=False,activeWrites=[]))
print(json.dumps({'wholeGoals':14,'prompts':14,'entry':REL+'/neutral-fourteen-image-prompts.author.entry.json','activeWrites':0}))
